import re

# Literal implementation of the criterion description.
# - First-person singular pronouns as whole words, case-insensitive.
# - A line starting with 'Note'/'Notes', optionally after '*', '_', '#', '>' markers.
# - Meta phrases: 'for your review', 'let me know', 'I omitted'.

_PRONOUN = re.compile(r"\b(?:i've|i'm|i'd|i'll|i|me|my)\b", re.IGNORECASE)
_NOTE_LINE = re.compile(r"^[ \t]*(?:[*_#>][ \t]*)*notes?\b", re.IGNORECASE | re.MULTILINE)
_PHRASES = re.compile(r"for\s+your\s+review|let\s+me\s+know|i\s+omitted", re.IGNORECASE)


def evaluate(output: str, inputs: dict) -> bool:
    if output is None:
        return True
    if not isinstance(output, str):
        output = str(output)
    if _PRONOUN.search(output):
        return False
    if _NOTE_LINE.search(output):
        return False
    if _PHRASES.search(output):
        return False
    return True

import re


def evaluate(output: str, inputs: dict) -> bool:
    """Literal reading of the criterion.

    - At least two lines that begin exactly with '## ' or '### ' (no leading
      whitespace allowed, exactly level 2 or 3).
    - No 'http://', 'https://', 'www.' substrings (case-insensitive) and no
      Markdown inline link pattern [text](url).
    """
    if not isinstance(output, str):
        return False

    lines = output.splitlines()
    subheading_count = 0
    for line in lines:
        if line.startswith('## ') or line.startswith('### '):
            subheading_count += 1
    if subheading_count < 2:
        return False

    lowered = output.lower()
    for token in ('http://', 'https://', 'www.'):
        if token in lowered:
            return False

    # Markdown inline link / image: [text](url)
    if re.search(r'\[[^\]]*\]\([^)]*\)', output):
        return False

    return True

import re

_HEADING_RE = re.compile(r'^ {0,3}(#{2,6})[ \t]+(.*?)[ \t]*#*[ \t]*$')
_FENCE_RE = re.compile(r'^ {0,3}(`{3,}|~{3,})')


def _count_subheadings(text: str) -> int:
    count = 0
    in_fence = False
    fence_char = None
    for line in text.splitlines():
        m = _FENCE_RE.match(line)
        if m:
            ch = m.group(1)[0]
            if not in_fence:
                in_fence = True
                fence_char = ch
            elif ch == fence_char:
                in_fence = False
                fence_char = None
            continue
        if in_fence:
            continue
        hm = _HEADING_RE.match(line)
        if hm and hm.group(2).strip().strip('#').strip():
            count += 1
    return count


def _has_link(text: str) -> bool:
    lowered = text.lower()
    # Bare URL markers
    if re.search(r'\b(?:https?|ftp)://', lowered):
        return True
    if 'www.' in lowered:
        return True
    if re.search(r'\bmailto:', lowered):
        return True
    # Inline markdown links / images: [text](target)
    if re.search(r'!?\[[^\]]*\]\([^)]*\)', text):
        return True
    # Autolinks: <scheme:...>
    if re.search(r'<[a-zA-Z][a-zA-Z0-9+.\-]{1,31}:[^\s<>]+>', text):
        return True
    # Reference-style link definitions: [ref]: target
    if re.search(r'(?m)^ {0,3}\[[^\]]+\]:\s*\S+', text):
        return True
    # Reference-style usage: [text][ref] (only if a matching definition exists
    # would it render, but treat any explicit [x][y] as a link attempt)
    if re.search(r'\[[^\]]+\]\[[^\]]*\]', text):
        return True
    return False


def evaluate(output: str, inputs: dict) -> bool:
    """CommonMark-aware interpretation.

    - Subheadings: ATX headings of level 2-6, allowing up to 3 leading spaces
      and optional closing hashes, with non-empty text, outside fenced code.
      Need at least two.
    - Links: any URL scheme marker, 'www.', mailto:, inline links/images,
      autolinks, or reference-style links/definitions.
    """
    if not isinstance(output, str) or not output.strip():
        return False
    if _count_subheadings(output) < 2:
        return False
    if _has_link(output):
        return False
    return True
